   ]
  },
  {
   "time": "2026-10-23T07:23:50Z",
   "event": "inventory starts logging 'connection pool exhausted'; orders logs 'inventory reservation failed with status 500'; gateway logs 'checkout failed: orders returned 502'",
   "evidence_ids": [
