   "evidence_ids": [
    "ev-eb1a06578431",
    "ev-bc2db81f526d",
    "ev-3cebf0e05abb"
   ]
  },
  {
   "time": "2026-10-23T07:25:38Z",
   "event": "First sampled error trace seen with path gateway 502 <- orders 502 <- inventory 500",
